/**
 * Roblox engine API data for script autocomplete (classes, enums, datatypes, libraries,
 * globals), generated by `scripts/gen-roblox-api.mjs` from the Roblox Creator
 * Documentation (CC BY 4.0). Loaded on demand, since it's only needed in the script editor.
 */

/** A class member, datatype member, library function or global. */
export type ApiMember = {
  /** Name, e.g. "WaitForChild". */
  n: string;
  /** p = property, m = method, e = event, c = callback, f = function (static/library/global). */
  k: "p" | "m" | "e" | "c" | "f";
  /** Property type, or a method/function's return type(s). */
  t?: string;
  /** Parameters: [name, type, default?]. */
  p?: [string, string, string?][];
  /** Short summary. */
  s?: string;
  /** Deprecated. */
  d?: 1;
  /** Read-only property. */
  ro?: 1;
  /** Yields. */
  y?: 1;
};

export type ApiClass = {
  super?: string;
  tags?: ("NotCreatable" | "Service" | "Deprecated")[];
  s?: string;
  members: ApiMember[];
};

export type Api = {
  about: { source: string; license: string; studioVersion: string };
  classes: Record<string, ApiClass>;
  enums: Record<string, string[]>;
  datatypes: Record<string, { statics: ApiMember[]; members: ApiMember[] }>;
  libraries: Record<string, ApiMember[]>;
  globals: ApiMember[];
};

let loading: Promise<Api> | null = null;
let loaded: Api | null = null;

export function loadApi(): Promise<Api> {
  loading ??= import("@/data/roblox-api.json").then((m) => {
    loaded = (m.default ?? m) as unknown as Api;
    return loaded;
  });
  return loading;
}

/** The API if it has finished loading (for synchronous callers). */
export const apiIfLoaded = () => loaded;

/** Every member of a class, including inherited ones (subclass members win). */
export function classMembers(api: Api, className: string): ApiMember[] {
  const seen = new Set<string>();
  const out: ApiMember[] = [];
  for (let c: string | undefined = className; c; c = api.classes[c]?.super) {
    for (const m of api.classes[c]?.members ?? []) {
      if (!seen.has(m.n)) {
        seen.add(m.n);
        out.push(m);
      }
    }
  }
  return out;
}

export function findMember(api: Api, className: string, name: string): ApiMember | undefined {
  for (let c: string | undefined = className; c; c = api.classes[c]?.super) {
    const m = api.classes[c]?.members.find((x) => x.n === name);
    if (m) return m;
  }
  return undefined;
}

export function isA(api: Api, className: string, ancestor: string) {
  for (let c: string | undefined = className; c; c = api.classes[c]?.super) {
    if (c === ancestor) return true;
  }
  return false;
}

const tagged = (c: ApiClass, tag: NonNullable<ApiClass["tags"]>[number]) => !!c.tags?.includes(tag);

/** Names for `game:GetService("…")`. */
export const serviceNames = (api: Api) =>
  Object.keys(api.classes).filter((n) => tagged(api.classes[n], "Service"));

/** Names for `Instance.new("…")`. */
export const creatableNames = (api: Api) =>
  Object.keys(api.classes).filter((n) => {
    const c = api.classes[n];
    return !tagged(c, "NotCreatable") && !tagged(c, "Service") && !tagged(c, "Deprecated");
  });

/** `(a: number, b: string?): Instance` */
export function signature(m: ApiMember) {
  const params = (m.p ?? [])
    .map(([n, t, d]) => (d !== undefined ? `${n}: ${t} = ${d}` : `${n}: ${t}`))
    .join(", ");
  return `(${params})${m.t ? `: ${m.t}` : ""}`;
}
